     1→import Phaser from 'phaser';
     2→
     3→export default class Player extends Phaser.Physics.Arcade.Sprite {
     4→  private cursors!: Phaser.Types.Input.Keyboard.CursorKeys;
     5→  private speed: number;
     6→  private baseSpeed: number; // 기본 속도 저장
     7→  private texturePrefix: string;
     8→  private leftKeyDown: boolean = false;
     9→  private rightKeyDown: boolean = false;
    10→  private readonly onKeyDown: (e: KeyboardEvent) => void;
    11→  private readonly onKeyUp: (e: KeyboardEvent) => void;
    12→
    13→  // 아이템 효과 상태
    14→  private isInvincible: boolean = false;
    15→  private speedBoostActive: boolean = false;
    16→
    17→  // 효과 타이머
    18→  private invincibleTimer?: Phaser.Time.TimerEvent;
    19→  private speedBoostTimer?: Phaser.Time.TimerEvent;
    20→  private rainbowTimer?: Phaser.Time.TimerEvent;
    21→
    22→  constructor(scene: Phaser.Scene, x: number, y: number, speed: number = 300, texturePrefix: string = '') {
    23→    // 기본 텍스처는 front (정면)
    24→    super(scene, x, y, `${texturePrefix}front`);
    25→    this.speed = speed;
    26→    this.baseSpeed = speed; // 기본 속도 저장
    27→    this.texturePrefix = texturePrefix;
    28→
    29→    // 씬에 추가
    30→    scene.add.existing(this);
    31→    scene.physics.add.existing(this);
    32→
    33→    // 캐릭터 크기 설정
    34→    this.setDisplaySize(50, 80);
    35→
    36→    // 히트박스를 몸통 중심부만 (더 작게)
    37→    // 원본 1024px → 256px (25%) 리사이즈에 맞춰 body 값도 25%
    38→    this.setSize(75, 163);
    39→    this.setOffset(69, 63);
    40→
    41→    // 물리 설정
    42→    this.setCollideWorldBounds(true);
    43→    this.setImmovable(true);
    44→
    45→    // Phaser 키보드 입력
    46→    this.cursors = scene.input.keyboard!.createCursorKeys();
    47→
    48→    // window 레벨 키보드 이벤트 (canvas 포커스와 무관하게 동작)
    49→    this.onKeyDown = (e: KeyboardEvent) => {
    50→      if (e.key === 'ArrowLeft') this.leftKeyDown = true;
    51→      if (e.key === 'ArrowRight') this.rightKeyDown = true;
    52→    };
    53→    this.onKeyUp = (e: KeyboardEvent) => {
    54→      if (e.key === 'ArrowLeft') this.leftKeyDown = false;
    55→      if (e.key === 'ArrowRight') this.rightKeyDown = false;
    56→    };
    57→    // capture: true → window capture phase는 이벤트 전파 최우선 단계
    58→    // Vercel Preview 툴바 등 외부 스크립트가 ArrowLeft/Right를 가로채도 우선 실행됨
    59→    window.addEventListener('keydown', this.onKeyDown, { capture: true });
    60→    window.addEventListener('keyup', this.onKeyUp, { capture: true });
    61→
    62→    // 씬 종료 시 이벤트 리스너 정리
    63→    scene.events.once('shutdown', this.removeKeyListeners, this);
    64→    scene.events.once('destroy', this.removeKeyListeners, this);
    65→  }
    66→
    67→  private removeKeyListeners() {
    68→    window.removeEventListener('keydown', this.onKeyDown, { capture: true });
    69→    window.removeEventListener('keyup', this.onKeyUp, { capture: true });
    70→  }
    71→
    72→  update() {
    73→    let isMoving = false;
    74→
    75→    // 좌우 이동 (Phaser 키보드 OR window 레벨 키보드 둘 다 체크)
    76→    if (this.cursors.left.isDown || this.leftKeyDown) {
    77→      this.setVelocityX(-this.speed);
    78→      this.setTexture(`${this.texturePrefix}left`);
    79→      isMoving = true;
    80→    } else if (this.cursors.right.isDown || this.rightKeyDown) {
    81→      this.setVelocityX(this.speed);
    82→      this.setTexture(`${this.texturePrefix}right`);
    83→      isMoving = true;
    84→    } else {
    85→      this.setVelocityX(0);
    86→    }
    87→
    88→    // 터치/마우스 입력 처리 (화면 중앙 기준)
    89→    if (this.scene.input.activePointer.isDown) {
    90→      const pointerX = this.scene.input.activePointer.x;
    91→      const screenCenter = this.scene.cameras.main.width / 2;
    92→
    93→      if (pointerX < screenCenter) {
    94→        this.setVelocityX(-this.speed);
    95→        this.setTexture(`${this.texturePrefix}left`); // 왼쪽 이미지
    96→        isMoving = true;
    97→      } else if (pointerX > screenCenter) {
    98→        this.setVelocityX(this.speed);
    99→        this.setTexture(`${this.texturePrefix}right`); // 오른쪽 이미지
   100→        isMoving = true;
   101→      }
   102→    }
   103→
   104→    // 멈춰있을 때는 정면 이미지
   105→    if (!isMoving && this.body?.velocity.x === 0) {
   106→      this.setTexture(`${this.texturePrefix}front`);
   107→    }
   108→  }
   109→
   110→  // 헤르메스 신발 효과: 10초간 속도 2배 증가
   111→  activateSpeedBoost(duration: number = 10000) {
   112→    // 기존 타이머가 있으면 제거
   113→    if (this.speedBoostTimer) {
   114→      this.speedBoostTimer.remove();
   115→    }
   116→
   117→    // 속도 증가 (2배)
   118→    this.speedBoostActive = true;
   119→    this.speed = this.baseSpeed * 2;
   120→
   121→    // 시각적 피드백: 노란색 틴트
   122→    this.setTint(0xffff00);
   123→
   124→    // 일정 시간 후 원래 속도로 복구
   125→    this.speedBoostTimer = this.scene.time.addEvent({
   126→      delay: duration,
   127→      callback: () => {
   128→        this.speedBoostActive = false;
   129→        this.speed = this.baseSpeed;
   130→        // 무적이 아니면 틴트 제거
   131→        if (!this.isInvincible) {
   132→          this.clearTint();
   133→        } else {
   134→          // 무적 효과만 남김
   135→          this.setTint(0x00ffff);
   136→        }
   137→      },
   138→      callbackScope: this
   139→    });
   140→  }
   141→
   142→  // 무지개 별 효과: 5초간 무적
   143→  activateInvincibility(duration: number = 5000) {
   144→    // 기존 타이머가 있으면 제거
   145→    if (this.invincibleTimer) {
   146→      this.invincibleTimer.remove();
   147→    }
   148→    if (this.rainbowTimer) {
   149→      this.rainbowTimer.remove();
   150→    }
   151→
   152→    // 무적 활성화
   153→    this.isInvincible = true;
   154→
   155→    // 무지개 색상 배열 (빨주노초파남보)
   156→    const rainbowColors = [
   157→      0xff0000, // 빨강
   158→      0xff7700, // 주황
   159→      0xffff00, // 노랑
   160→      0x00ff00, // 초록
   161→      0x00ffff, // 하늘
   162→      0x0000ff, // 파랑
   163→      0xff00ff  // 보라
   164→    ];
   165→
   166→    let colorIndex = 0;
   167→
   168→    // 무지개 색상 순환 효과 (150ms마다 색상 변경)
   169→    this.rainbowTimer = this.scene.time.addEvent({
   170→      delay: 150,
   171→      callback: () => {
   172→        this.setTint(rainbowColors[colorIndex]);
   173→        colorIndex = (colorIndex + 1) % rainbowColors.length;
   174→      },
   175→      callbackScope: this,
   176→      loop: true
   177→    });
   178→
   179→    // 일정 시간 후 무적 해제
   180→    this.invincibleTimer = this.scene.time.addEvent({
   181→      delay: duration,
   182→      callback: () => {
