    71→    // ── 배경: 선택된 캐릭터 일러스트 ───────────────────────────────────
    72→    this.bgImage = this.add.image(200, 300, selectedDef.illustKey);
    73→    this.bgImage.setDisplaySize(400, 600);
    74→
    75→    // ── 헤더 (고정) ─────────────────────────────────────────────────────
    76→    this.add.text(200, 40, '캐릭터 선택', {
    77→      fontSize: '26px',
    78→      color: '#ffffff',
    79→      fontStyle: 'bold',
    80→      stroke: '#000',
    81→      strokeThickness: 4,
    82→    }).setOrigin(0.5);
    83→
    84→    this.headerNameText = this.add.text(200, 80, `현재: ${selectedDef.name}`, {
    85→      fontSize: '16px',
    86→      color: selectedDef.gradeColor,
    87→      stroke: '#000',
    88→      strokeThickness: 3,
    89→    }).setOrigin(0.5);
    90→
    91→    this.add.text(200, 108, '수집한 캐릭터를 선택하세요', {
    92→      fontSize: '13px',
    93→      color: '#888888',
    94→    }).setOrigin(0.5);
    95→
    96→    // ── 스크롤 가능한 카드 컨테이너 ─────────────────────────────────────
    97→    this.cardsContainer = this.add.container(0, 0);
    98→
    99→    CHARACTERS.forEach((char, index) => {
   100→      const col = index % COLS;
   101→      const row = Math.floor(index / COLS);
   102→      const x = GRID_LEFT + col * (CARD_W + GAP_X) + CARD_W / 2;
   103→      const y = GRID_TOP + row * (CARD_H + GAP_Y) + CARD_H / 2;
   104→      this.createCharacterCard(char, x, y);
   105→    });
   106→
   107→    // 스크롤 최대 범위 계산
   108→    const totalRows = Math.ceil(CHARACTERS.length / COLS);
   109→    const contentBottom = GRID_TOP + (totalRows - 1) * (CARD_H + GAP_Y) + CARD_H + 10;
   110→    this.maxScrollOffset = Math.max(0, contentBottom - SCROLL_BOTTOM);
   111→
   112→    // 카드 영역 마스크 (스크롤 영역 밖 숨김)
   113→    const maskGfx = this.make.graphics({ x: 0, y: 0 });
   114→    maskGfx.fillStyle(0xffffff);
   115→    maskGfx.fillRect(0, SCROLL_TOP, 400, SCROLL_BOTTOM - SCROLL_TOP);
   116→    this.cardsContainer.setMask(maskGfx.createGeometryMask());
   117→
   118→    // ── 드래그 스크롤 입력 ───────────────────────────────────────────────
   119→    this.input.on('pointerdown', (p: Phaser.Input.Pointer) => {
   120→      if (this.detailPanel) return; // 상세 패널 열려있으면 스크롤 무시
   121→      if (p.y < SCROLL_TOP || p.y > SCROLL_BOTTOM) return;
   122→      this.pointerDownY = p.y;
   123→      this.pointerDownScrollY = this.scrollOffset;
   124→      this.hasDragged = false;
   125→    });
   126→
   127→    this.input.on('pointermove', (p: Phaser.Input.Pointer) => {
   128→      if (this.detailPanel) return; // 상세 패널 열려있으면 스크롤 무시
   129→      if (!p.isDown) return;
   130→      const dy = this.pointerDownY - p.y;
   131→      if (Math.abs(dy) > 5) {
   132→        this.hasDragged = true;
   133→        this.scrollOffset = Phaser.Math.Clamp(
   134→          this.pointerDownScrollY + dy,
   135→          0,
   136→          this.maxScrollOffset,
   137→        );
   138→        this.cardsContainer.setY(-this.scrollOffset);
   139→      }
   140→    });
   141→
   142→    this.input.on('pointerup', () => {
   143→      if (this.detailPanel) return; // 상세 패널 열려있으면 hasDragged 초기화 무시
   144→      // card pointerup 이벤트가 먼저 발생하므로 다음 프레임에 초기화
   145→      this.time.delayedCall(0, () => { this.hasDragged = false; });
   146→    });
   147→
   148→    // 마우스 휠
   149→    this.input.on(
   150→      'wheel',
   151→      (_p: Phaser.Input.Pointer, _go: unknown[], _dx: number, deltaY: number) => {
   152→        if (this.detailPanel) return; // 상세 패널 열려있으면 휠 스크롤 무시
   153→        this.scrollOffset = Phaser.Math.Clamp(
   154→          this.scrollOffset + deltaY * 0.5,
   155→          0,
   156→          this.maxScrollOffset,
   157→        );
   158→        this.cardsContainer.setY(-this.scrollOffset);
   159→      },
   160→    );
   161→
   162→    // ── 고정 UI ─────────────────────────────────────────────────────────
   163→    this.createBackButton();
   164→  }
