   166→  private createCharacterCard(char: CharacterDef, x: number, y: number) {
   167→    const isOwned = this.ownedIds.includes(char.id);
   168→    const isSelected = this.selectedId === char.id;
   169→    const gradeColorInt = parseInt(char.gradeColor.replace('#', ''), 16);
   170→
   171→    // 카드 배경
   172→    const cardBg = this.add.rectangle(x, y, CARD_W, CARD_H, 0x222222);
   173→    cardBg.setStrokeStyle(2, isOwned ? gradeColorInt : 0x444444);
   174→    this.cardsContainer.add(cardBg);
   175→
   176→    // 선택 하이라이트
   177→    const highlight = this.add.rectangle(x, y, CARD_W, CARD_H, 0, 0);
   178→    highlight.setStrokeStyle(3, 0xffffff);
   179→    highlight.setVisible(isSelected);
   180→    this.cardHighlights.set(char.id, highlight);
   181→    this.cardsContainer.add(highlight);
   182→
   183→    // 캐릭터 이미지
   184→    const img = this.add.image(x, y - 12, char.imageKey);
   185→    img.setDisplaySize(58, 85);
   186→    this.cardsContainer.add(img);
   187→
   188→    if (!isOwned) {
   189→      img.setTint(0x000000);
   190→      img.setAlpha(0.6);
   191→      const lock = this.add.text(x, y - 12, '🔒', { fontSize: '22px' }).setOrigin(0.5);
   192→      this.cardsContainer.add(lock);
   193→    }
   194→
   195→    // 등급 배지
   196→    const badge = this.add.text(x + CARD_W / 2 - 2, y - CARD_H / 2 + 2, char.grade, {
   197→      fontSize: '9px',
   198→      color: char.gradeColor,
   199→      fontStyle: 'bold',
   200→      backgroundColor: '#000000cc',
   201→      padding: { x: 3, y: 1 },
   202→    }).setOrigin(1, 0);
   203→    this.cardsContainer.add(badge);
   204→
   205→    // 캐릭터 이름
   206→    const nameText = this.add.text(x, y + CARD_H / 2 - 16, char.name, {
   207→      fontSize: '12px',
   208→      color: isOwned ? '#ffffff' : '#555555',
   209→      fontStyle: 'bold',
   210→    }).setOrigin(0.5);
   211→    this.cardsContainer.add(nameText);
   212→
   213→    // 모든 카드 클릭 가능 (탭 → 상세 패널 열기)
   214→    cardBg.setInteractive({ useHandCursor: isOwned });
   215→
   216→    if (isOwned) {
   217→      cardBg.on('pointerover', () => {
   218→        if (this.selectedId !== char.id) cardBg.setFillStyle(0x333333);
   219→      });
   220→      cardBg.on('pointerout', () => {
   221→        if (this.selectedId !== char.id) cardBg.setFillStyle(0x222222);
   222→      });
   223→    }
   224→    // pointerup으로 상세 패널 열기 (드래그 스크롤과 구분)
   225→    cardBg.on('pointerup', () => {
   226→      if (!this.hasDragged) this.showCharacterDetail(char.id);
   227→    });
   228→  }
