   351→      // 일러스트 탭 → 비디오 재생 (가챠와 동일한 fitVideo 방식)
   352→      // active 체크: ✕ 탭 시 패널 파괴 직후 이 핸들러가 동시에 발화하는 경우 방지
   353→      const startVideo = () => {
