   375→  /** GachaScene.fitVideoToCanvas와 동일 — aspect ratio 유지하며 400×600 캔버스에 cover */
   376→  private fitVideoToPanel(vid: Phaser.GameObjects.Video): void {
   377→    const W = 400, H = 600;
   378→    vid.setDisplaySize(W, H);
   379→
   380→    const applyContain = () => {
   381→      // eslint-disable-next-line @typescript-eslint/no-explicit-any
   382→      const el: HTMLVideoElement | null = (vid as any).video ?? null;
   383→      const nw = el?.videoWidth  || 0;
   384→      const nh = el?.videoHeight || 0;
   385→      if (nw > 0 && nh > 0) {
   386→        const scale = Math.max(W / nw, H / nh);
   387→        vid.setDisplaySize(Math.round(nw * scale), Math.round(nh * scale));
   388→      }
   389→    };
   390→
   391→    vid.once('play', applyContain);
   392→    this.time.delayedCall(100, applyContain);
   393→    this.time.delayedCall(500, applyContain);
   394→  }
